begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(11);
create temporary table m15_05_validation_values(k text primary key,v jsonb);
insert into m15_05_validation_values values('configuration','{"sourceAlias":"source","repositoryAlias":"off-host","stagingAlias":"private-ram","keyAlias":"backup-key","targetProfile":"isolated-saas","residency":"eu","schedulingEnabled":false,"checkpointIntervalMinutes":30,"baseIntervalHours":24,"verificationIntervalDays":30,"retentionDays":30,"pauseLimitSeconds":120}');
insert into m15_05_validation_values select 'validation',public.m15_05_backup_control('15000000-0000-4000-8000-000000000060','backup-sql-fixture','policy/validate',jsonb_build_object('configuration',v)) from m15_05_validation_values where k='configuration';
select is((select v->'result'->>'valid' from m15_05_validation_values where k='validation'),'false','initial config requires native validation');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000060','backup-sql-fixture','policy/read','{}')->'result','null'::jsonb,'pending configuration is not authoritative');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000060','backup-sql-fixture','policy/update',jsonb_build_object('expectedVersion',0,'idempotencyKey','15000000-0000-4000-8000-000000000061','configuration',(select v from m15_05_validation_values where k='configuration')))->>'outcome','blocked','unvalidated draft cannot be approved');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000060','backup-sql-fixture','policy/validation-failed',jsonb_build_object('configurationDigest',(select v->'result'->>'configurationDigest' from m15_05_validation_values where k='validation'),'failureCode','key_unavailable'))->>'outcome','ok','safe native failure persisted');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000060','backup-sql-fixture','policy/validation-failed',jsonb_build_object('configurationDigest',(select v->'result'->>'configurationDigest' from m15_05_validation_values where k='validation'),'failureCode','key_unavailable'))->>'outcome','ok','repeated candidate failure replays safely');
select is((select count(*)::integer from public.audit_logs where entity_id='15000000-0000-4000-8000-000000000060' and action='backup.validation_failed'),1,'same candidate and failure code are durably deduplicated');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000060','backup-sql-fixture','policy/validate',jsonb_build_object('configuration',(select v from m15_05_validation_values where k='configuration')))->'result'->'checks'->0->>'code','key_unavailable','customer sees safe fixed failure rather than perpetual unknown');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000060','backup-sql-fixture','policy/validation-failed',jsonb_build_object('configurationDigest',(select v->'result'->>'configurationDigest' from m15_05_validation_values where k='validation'),'failureCode','postgres://credential'))->>'outcome','invalid','unregistered error details rejected');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000060','backup-sql-fixture','policy/validated',jsonb_build_object('configurationDigest',(select v->'result'->>'configurationDigest' from m15_05_validation_values where k='validation')))->>'outcome','ok','executor records successful native retry');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000060','backup-sql-fixture','policy/validate',jsonb_build_object('configuration',(select v from m15_05_validation_values where k='configuration')))->'result'->>'valid','true','fresh matching native proof clears prior failure');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000060','backup-sql-fixture','policy/update',jsonb_build_object('expectedVersion',0,'idempotencyKey','15000000-0000-4000-8000-000000000061','configuration',(select v from m15_05_validation_values where k='configuration')))->'result'->>'version','1','explicit approval atomically promotes validated draft');
select * from finish();
rollback;
